1	/** A live cell's position on the infinite grid, as `[x, y]`. */
2	export type Cell = [number, number];
3	
4	/**
5	 * A `Cell` flattened to a string so it can be used as a `Set`/`Map` key —
6	 * JavaScript keys arrays by identity, so two distinct `[0, 0]` tuples would
7	 * otherwise never collide.
8	 */
9	type CellKey = string;
10	
11	const toKey = ([x, y]: Cell): CellKey => `${x},${y}`;
12	
13	const fromKey = (key: CellKey): Cell => {
14	  const [x, y] = key.split(",");
15	  return [Number(x), Number(y)];
16	};
17	
18	/** The eight positions surrounding a cell on the grid. */
19	const neighborsOf = ([x, y]: Cell): Cell[] => {
20	  const neighbors: Cell[] = [];
21	  for (let dx = -1; dx <= 1; dx++) {
22	    for (let dy = -1; dy <= 1; dy++) {
23	      if (dx !== 0 || dy !== 0) neighbors.push([x + dx, y + dy]);
24	    }
25	  }
26	  return neighbors;
27	};
28	
29	/**
30	 * Tallies, for every cell adjacent to at least one live cell, how many live
31	 * neighbors it has. Cells with a count of zero are absent, which is exactly
32	 * the set that can never change state — so this is also the candidate set.
33	 */
34	const countLiveNeighbors = (liveCells: Cell[]): Map<CellKey, number> => {
35	  const counts = new Map<CellKey, number>();
36	  for (const cell of liveCells) {
37	    for (const neighbor of neighborsOf(cell)) {
38	      const key = toKey(neighbor);
39	      counts.set(key, (counts.get(key) ?? 0) + 1);
40	    }
41	  }
42	  return counts;
43	};
44	
45	/**
46	 * Advances the board one generation. The board is represented sparsely: only
47	 * live cells are listed, so any coordinate absent from `liveCells` is dead.
48	 */
49	export function nextGeneration(liveCells: Cell[]): Cell[] {
50	  const live = new Set(liveCells.map(toKey));
51	
52	  const nextLiveCells: Cell[] = [];
53	  for (const [key, liveNeighbors] of countLiveNeighbors(liveCells)) {
54	    const survives =
55	      live.has(key) && (liveNeighbors === 2 || liveNeighbors === 3);
56	    const isBorn = !live.has(key) && liveNeighbors === 3;
57	    if (survives || isBorn) nextLiveCells.push(fromKey(key));
58	  }
59	
60	  return nextLiveCells;
61	}
